import squizStoryRenderer from '@ntgovernment/squiz-factory/plugins/squizStoryRenderer';
import squizInfoMock from '@ntgovernment/squiz-factory/plugins/squizInfo.mock';
import comp from './main.js';



function fakeImageAsset({ id, name, alt }) {
  return {
    type: 'type_image',
    name,
    alt,
    caption: name,
    imageVariations: {
      original: {
        url: `https://picsum.photos/id/${id}/640/480`,
        width: 640,
        height: 480,
        mimeType: 'image/jpeg',
        byteSize: 65536,
        sha1Hash: `${id}aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa`.slice(0, 40),
        aspectRatio: '4:3',
      },
    },
  };
}

/**
 * This component resolves each entry in `imageSources` at render time via
 * info.fns.resolveUri(source), a real DXP edge capability the local dev-ui's
 * own mock does not exercise meaningfully (it always returns a generic fake
 * "page" asset, regardless of the URI). These fake assets exist purely so
 * the multi-source/folder-expansion *logic* in main.js can be verified here
 * in Storybook -- they say nothing about what a real connected Matrix
 * backend actually returns. See the spec's assumptions.
 */
const FAKE_ASSETS = {
  'matrix-asset://demo-single-image': fakeImageAsset({
    id: 1015,
    name: 'Mountain Serenity',
    alt: 'Scenic mountain landscape with gradient sky and green fields',
  }),
  'matrix-asset://demo-single-image-2': fakeImageAsset({
    id: 1016,
    name: 'Urban Exploration',
    alt: 'Urban scene with grey tones and industrial elements',
  }),
  'matrix-asset://demo-folder': {
    type: 'type_folder',
    name: 'Demo Gallery Folder',
    children: [1015, 1016, 1018, 1019, 1021, 1024, 1027, 1035].map((id, index) => fakeImageAsset({
      id,
      name: `Image ${index + 1}`,
      alt: `Gallery demonstration image ${index + 1}`,
    })),
  },
  'matrix-asset://demo-empty-folder': {
    type: 'type_folder',
    name: 'Empty Folder',
    children: [],
  },
};

function resolveUriMock(uri) {
  return FAKE_ASSETS[uri] ?? null;
}

/**
 * squizStoryRenderer's installed signature only takes `main` -- it does not
 * accept a second (resolveUri-mock) constructor argument, so that argument
 * was previously silently ignored. The returned render function's own
 * `info` parameter must be supplied at each call site instead; without it,
 * every story rendered an empty grid (`resolveImages` bails out as soon as
 * `typeof fns?.resolveUri !== 'function'`) even though the separately
 * precomputed "Show code" HTML (built via a direct `comp.main(args,
 * mockInfo)` call below) looked correct.
 */
const squiz = squizStoryRenderer(comp.main);
const mockInfo = squizInfoMock({ mock: { resolveUri: resolveUriMock } });

export default {
  title: 'dxp/Image Gallery',
};

const singleImageArgs = { imageSources: ['matrix-asset://demo-single-image'] };
const singleImageHtml = await squiz.markup(singleImageArgs, mockInfo);

export const SingleImage = {
  render: (args) => squiz(args, mockInfo),
  args: singleImageArgs,
  argTypes: {
    imageSources: {
      control: 'object',
      description: 'Array of matrix-asset-uri strings, each a single image or a folder. Only these demo URIs resolve to anything in this Storybook preview (mocked): matrix-asset://demo-single-image, matrix-asset://demo-single-image-2, matrix-asset://demo-folder, matrix-asset://demo-empty-folder.',
    },
  },
  parameters: {
    docs: {
      description: { story: 'imageSources has one entry pointing directly at a single image asset -- the gallery shows just that one image.' },
      source: { code: singleImageHtml, language: 'html', type: 'code' },
    },
  },
};

const multipleImagesArgs = { imageSources: ['matrix-asset://demo-single-image', 'matrix-asset://demo-single-image-2'] };
const multipleImagesHtml = await squiz.markup(multipleImagesArgs, mockInfo);

export const MultipleImages = {
  render: () => squiz(multipleImagesArgs, mockInfo),
  parameters: {
    docs: {
      description: { story: 'imageSources has two individually-picked image entries -- no folder involved. Demonstrates that the field supports selecting several images directly, not just one.' },
      source: { code: multipleImagesHtml, language: 'html', type: 'code' },
    },
  },
};

const folderArgs = { imageSources: ['matrix-asset://demo-folder'] };
const folderHtml = await squiz.markup(folderArgs, mockInfo);

export const Folder = {
  render: () => squiz(folderArgs, mockInfo),
  parameters: {
    docs: {
      description: { story: 'imageSources has one entry pointing at a folder; every image resolved as a child of that folder is rendered in the grid.' },
      source: { code: folderHtml, language: 'html', type: 'code' },
    },
  },
};

const mixedArgs = { imageSources: ['matrix-asset://demo-single-image', 'matrix-asset://demo-folder'] };
const mixedHtml = await squiz.markup(mixedArgs, mockInfo);

export const Mixed = {
  render: () => squiz(mixedArgs, mockInfo),
  parameters: {
    docs: {
      description: { story: 'imageSources combines one individually-picked image with one folder -- the gallery is the union of both (the individual image plus every image in the folder).' },
      source: { code: mixedHtml, language: 'html', type: 'code' },
    },
  },
};

const emptyFolderArgs = { imageSources: ['matrix-asset://demo-empty-folder'] };
const emptyFolderHtml = await squiz.markup(emptyFolderArgs, mockInfo);

export const EmptyFolder = {
  render: () => squiz(emptyFolderArgs, mockInfo),
  parameters: {
    docs: {
      description: { story: 'A folder with no images resolves to an empty gallery grid, not an error.' },
      source: { code: emptyFolderHtml, language: 'html', type: 'code' },
    },
  },
};

const unresolvableArgs = { imageSources: ['matrix-asset://does-not-exist'] };
const unresolvableHtml = await squiz.markup(unresolvableArgs, mockInfo);

export const Unresolvable = {
  render: () => squiz(unresolvableArgs, mockInfo),
  parameters: {
    docs: {
      description: { story: 'A source that fails to resolve at all contributes nothing, rendering an empty gallery rather than throwing.' },
      source: { code: unresolvableHtml, language: 'html', type: 'code' },
    },
  },
};
